1	/* ============================ Người treo dù: trang bị bằng code ============================
2	   Một BufferGeometry có xương (skinIndex / skinWeight) cho SkinnedMesh: đai ngồi, ba lô + hộp dù dự phòng, đai vai / ngực / đùi, khóa, carabiner, riser, quai phanh, dây phanh, dây treo.
3	   Mỗi đỉnh gắn cứng một xương (trọng số 1). Dây và đai nối hai xương là lăng trụ có đáy một xương, đỉnh một xương nên hai đầu luôn bám dù lẫn người khi xương dịch chuyển.
4	   Hệ tọa độ: hệ group dù (+X bay, +Y lên, +Z phải); mọi bộ phận dựng theo vị trí nghỉ của xương truyền vào (PlGearRest), không có số tuyệt đối.
5	   Thuần BufferGeometry, không cần DOM nên test node dùng được. Thông số: CONFIG.explore.pilot.gear. */
6	import * as THREE from 'three';
7	import { CONFIG } from '../../config';
8	import { exLineTops, exBrakeTops } from '../glider';
9	
10	/* Thứ tự xương = giá trị skinIndex. 'wing' là gốc cánh (đầu trên của dây), 'pack' là ba lô lệch pha với thân */
11	export const PL_GEAR_BONES = ['wing', 'hang', 'pelvis', 'spine', 'handL', 'handR', 'thighL', 'thighR', 'pack'] as const;
12	export interface PlGearRest { hang: number[]; pelvis: number[]; spine: number[]; handL: number[]; handR: number[]; thighL: number[]; thighR: number[] }   // vị trí nghỉ từng xương trong hệ group dù, m
13	
14	const PG = CONFIG.explore.pilot, GC = PG.gear;
15	const BI = (n: typeof PL_GEAR_BONES[number]): number => PL_GEAR_BONES.indexOf(n);
16	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
17	const COL = (hex: string): number[] => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };
18	
19	/* Bộ gom đỉnh không chỉ số: mỗi tam giác có pháp tuyến phẳng, màu và xương theo đỉnh */
20	class GearBuf {
21	  pos: number[] = []; nor: number[] = []; col: number[] = []; si: number[] = [];
22	  /* Một tam giác; ba xương theo ba đỉnh */
23	  tri(a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3, ba: number, bb: number, bc: number, rgb: number[]): void {
24	    const n = b.clone().sub(a).cross(c.clone().sub(a));
25	    if (n.lengthSq() < 1e-14) return;
26	    n.normalize();
27	    for (const [p, bone] of [[a, ba], [b, bb], [c, bc]] as [THREE.Vector3, number][]) {
28	      this.pos.push(p.x, p.y, p.z); this.nor.push(n.x, n.y, n.z); this.col.push(rgb[0], rgb[1], rgb[2]); this.si.push(bone);
29	    }
30	  }
31	  /* Mặt bốn đỉnh; ref nằm bên trong khối, mặt luôn quay ra xa ref */
32	  quad(p: THREE.Vector3[], bn: number[], rgb: number[], ref: THREE.Vector3): void {
33	    const ctr = p[0].clone().add(p[1]).add(p[2]).add(p[3]).multiplyScalar(0.25);
34	    const n = p[1].clone().sub(p[0]).cross(p[2].clone().sub(p[0]));
35	    const o = n.dot(ctr.sub(ref)) < 0 ? [0, 3, 2, 1] : [0, 1, 2, 3];
36	    this.tri(p[o[0]], p[o[1]], p[o[2]], bn[o[0]], bn[o[1]], bn[o[2]], rgb);
37	    this.tri(p[o[0]], p[o[2]], p[o[3]], bn[o[0]], bn[o[2]], bn[o[3]], rgb);
38	  }
39	  /* Hộp theo trục tọa độ, tâm c, nửa kích thước h, một xương */
40	  box(c: THREE.Vector3, h: number[], bone: number, rgb: number[]): void {
41	    for (let ax = 0; ax < 3; ax++) {
42	      const u = (ax + 1) % 3, v = (ax + 2) % 3;
43	      for (const sg of [-1, 1]) {
44	        const q: THREE.Vector3[] = [];
45	        for (const [su, sv] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
46	          const o = [0, 0, 0]; o[ax] = sg * h[ax]; o[u] = su * h[u]; o[v] = sv * h[v];
47	          q.push(V(c.x + o[0], c.y + o[1], c.z + o[2]));
48	        }
49	        this.quad(q, [bone, bone, bone, bone], rgb, c);
50	      }
51	    }
52	  }
53	  /* Lăng trụ bốn cạnh từ a tới b: mặt cắt w × t, w dọc theo hint (đã chiếu vuông góc trục); đáy a gắn xương ba, đáy b gắn xương bb. Dây: w = t = 2·bán kính */
54	  prism(a: THREE.Vector3, b: THREE.Vector3, ba: number, bb: number, rgb: number[], w: number, t: number, hint = V(0, 0, 1)): void {
55	    const d = b.clone().sub(a);
56	    if (d.length() < 1e-4) return;
57	    d.normalize();
58	    let u = hint.clone().sub(d.clone().multiplyScalar(hint.dot(d)));
59	    if (u.lengthSq() < 1e-6) u = Math.abs(d.y) < 0.9 ? V(0, 1, 0).sub(d.clone().multiplyScalar(d.y)) : V(1, 0, 0).sub(d.clone().multiplyScalar(d.x));
60	    u.normalize();
61	    const v = d.clone().cross(u).normalize();
62	    const ring = (o: THREE.Vector3) => [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => o.clone().addScaledVector(u, s * w / 2).addScaledVector(v, r * t / 2));
63	    const ra = ring(a), rb = ring(b), ref = a.clone().add(b).multiplyScalar(0.5);
64	    for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [ba, ba, bb, bb], rgb, ref);
65	  }
66	  geometry(): THREE.BufferGeometry {
67	    const g = new THREE.BufferGeometry(), n = this.si.length;
68	    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
69	    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
70	    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
71	    const idx = new Uint16Array(n * 4), wt = new Float32Array(n * 4);
72	    for (let i = 0; i < n; i++) { idx[i * 4] = this.si[i]; wt[i * 4] = 1; }
73	    g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(idx, 4));
74	    g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(wt, 4));
75	    return g;
76	  }
77	}
78	
79	/* Dựng toàn bộ trang bị quanh các vị trí nghỉ của xương */
80	export function plGearGeometry(rest: PlGearRest): THREE.BufferGeometry {
81	  const b = new GearBuf(), C = GC.colors, bd = GC.body, gap = GC.gap;
82	  const harness = COL(C.harness), strap = COL(C.strap), pack = COL(C.pack), toggle = COL(C.toggle), line = COL(C.line), metal = COL(C.metal), red = COL(C.reserve);
83	  const H = rest.hang, Pl = rest.pelvis, S = rest.spine;
84	  const bone = { wing: BI('wing'), hang: BI('hang'), pel: BI('pelvis'), spine: BI('spine'), pack: BI('pack') };
85	  const tc = S[0], py = Pl[1];                              // tâm thân theo X, cao độ hông
86	  const backX = tc - bd.chestDepth / 2 - gap, frontX = tc + bd.chestDepth / 2 + gap;   // mặt lưng / mặt ngực cộng khe hở
87	  const sz = bd.shoulderHalf - 0.03, W = GC.strapW, T = GC.strapT, X = V(1, 0, 0), Y = V(0, 1, 0), Z = V(0, 0, 1);
88	
89	  /* Đai ngồi kiểu ghế: tấm ngồi, hai má hông, tấm lưng dưới (hông) và trên (cột sống) */
90	  b.box(V(Pl[0] + 0.03, py - 0.125, 0), [0.21, 0.025, bd.hipWidth / 2 + 0.03], bone.pel, harness);
91	  for (const s of [-1, 1]) b.box(V(Pl[0] + 0.01, py - 0.02, s * (bd.hipWidth / 2 + gap + 0.02)), [0.16, 0.08, 0.02], bone.pel, harness);
92	  b.box(V(backX - 0.025, py + 0.05, 0), [0.025, 0.10, 0.17], bone.pel, harness);
93	  b.box(V(backX - 0.025, py + 0.325, 0), [0.025, 0.175, 0.17], bone.spine, harness);
94	
95	  /* Ba lô sau lưng (xương pack lệch pha), hộp dù dự phòng dưới ghế, quai kéo dù dự phòng màu đỏ */
96	  const gp = GC.pack;
97	  b.box(V(backX - 0.05 - gp.depth / 2, py + 0.05 + gp.height / 2, 0), [gp.depth / 2, gp.height / 2, gp.width / 2], bone.pack, pack);
98	  b.box(V(Pl[0] - 0.01, py - 0.15 - gp.reserveH / 2, 0), [0.17, gp.reserveH / 2, 0.15], bone.pack, pack);
99	  const ry = py - 0.15 - gp.reserveH / 2;
100	  b.prism(V(Pl[0], ry, 0.15), V(Pl[0] + 0.10, ry, 0.20), bone.pack, bone.pack, red, 0.03, 0.012, Y);
101	  b.box(V(Pl[0] + 0.12, ry, 0.205), [0.03, 0.02, 0.01], bone.pack, red);
102	
103	  /* Đai vai: từ lưng qua vai, xuống ngực, tới mép trước ghế; đai nối từ vai tới carabiner */
104	  for (const s of [-1, 1]) {
105	    const back = V(backX, py + bd.shoulderUp - 0.03, s * sz), top = V(tc, py + bd.shoulderUp + 0.04 + gap, s * sz), front = V(frontX, py + 0.30, s * sz);
106	    const seatF = V(Pl[0] + 0.15, py - 0.09, s * (bd.hipWidth / 2 - 0.03));
107	    b.prism(back, top, bone.spine, bone.spine, strap, W, T, Z);
108	    b.prism(top, front, bone.spine, bone.spine, strap, W, T, Z);
109	    b.prism(front, seatF, bone.spine, bone.pel, strap, W, T, Z);
110	    /* Carabiner: khung chữ nhật trong mặt phẳng X-Y ở điểm treo, gắn đai ngồi; riser từ móc lên điểm tụ dây (đầu trên gắn xương hang) */
111	    const c = V(H[0], H[1], s * PG.hang.half), cw = GC.carab.w / 2, ch = GC.carab.h / 2, cb = GC.carab.bar;
112	    const k = [V(c.x + cw, c.y + ch, c.z), V(c.x - cw, c.y + ch, c.z), V(c.x - cw, c.y - ch, c.z), V(c.x + cw, c.y - ch, c.z)];
113	    for (let i = 0; i < 4; i++) b.prism(k[i], k[(i + 1) % 4], bone.pel, bone.pel, metal, cb, cb);
114	    b.prism(top, V(c.x - cw, c.y + ch, c.z), bone.spine, bone.pel, strap, W, T, Z);
115	    const riserTop = V(c.x, c.y + PG.riser, c.z);
116	    b.prism(V(c.x, c.y + ch, c.z), riserTop, bone.pel, bone.hang, strap, W * 0.8, T, X);
117	    /* Dây treo: lineCount dây từ đầu riser lên cánh */
118	    for (const t of exLineTops()) if (t.side === s) b.prism(riserTop, V(t.x, t.y, t.z), bone.hang, bone.wing, line, GC.lineR * 2, GC.lineR * 2);
119	  }
120	
121	  /* Đai ngực (hai nửa, chừa khe cho khóa) + khóa kim loại */
122	  for (const s of [-1, 1]) b.prism(V(frontX + 0.005, py + 0.30, s * sz), V(frontX + 0.005, py + 0.30, s * 0.035), bone.spine, bone.spine, strap, W * 0.8, T, Y);
123	  b.box(V(frontX + 0.012, py + 0.30, 0), [0.012, 0.022, 0.032], bone.spine, metal);
124	
125	  /* Đai đùi: vòng tám cạnh quanh đùi (gắn xương đùi), đai nối tới mép ghế, khóa ở phía trên */
126	  for (const s of [-1, 1]) {
127	    const Tg = s < 0 ? rest.thighL : rest.thighR, bt = BI(s < 0 ? 'thighL' : 'thighR');
128	    const r = bd.thighR + gap + T, cx = Tg[0] + 0.14, cy = Tg[1] - 0.02, cz = Tg[2];
129	    const ring: THREE.Vector3[] = [];
130	    for (let i = 0; i < 8; i++) { const an = i * Math.PI / 4; ring.push(V(cx, cy + r * Math.cos(an), cz + r * Math.sin(an))); }
131	    for (let i = 0; i < 8; i++) b.prism(ring[i], ring[(i + 1) % 8], bt, bt, strap, W, T, X);
132	    b.prism(V(Pl[0] + 0.10, py - 0.09, s * (bd.hipWidth / 2 + 0.03)), V(cx, cy + r * 0.7071, cz + s * r * 0.7071), bone.pel, bt, strap, W, T, Y);
133	    b.box(V(cx, cy + r + 0.004, cz), [0.02, 0.008, 0.025], bt, metal);
134	  }
135	
136	  /* Quai phanh ×2 gắn xương bàn tay; dây phanh tụ về một điểm trên quai rồi chia ba nhánh lên mép sau cánh */
137	  for (const s of [-1, 1]) {
138	    const hd = s < 0 ? rest.handL : rest.handR, bh = BI(s < 0 ? 'handL' : 'handR');
139	    const hp = V(hd[0], hd[1], hd[2]), join = V(hd[0], hd[1] + GC.brakeJoin, hd[2]);
140	    b.prism(V(hd[0], hd[1], hd[2] - 0.05), V(hd[0], hd[1], hd[2] + 0.05), bh, bh, toggle, 0.022, 0.022);
141	    b.prism(hp, join, bh, bh, line, GC.lineR * 2, GC.lineR * 2);
142	    for (const t of exBrakeTops()) if (t.side === s) b.prism(join, V(t.x, t.y, t.z), bh, bone.wing, line, GC.lineR * 2, GC.lineR * 2);
143	  }
144	  return b.geometry();
145	}
146	
147	/* Vật liệu dùng chung: màu theo đỉnh, nhám, không kim loại để cả trang bị vẫn 1 lệnh vẽ. DoubleSide vì đai và dây là lăng trụ không nắp */
148	let plGearMat: THREE.MeshStandardMaterial | null = null;
149	export function plGearMaterial(): THREE.MeshStandardMaterial {
150	  return plGearMat ??= new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0.1, side: THREE.DoubleSide });
151	}
