211	  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, map: tex.map, roughness: G.roughness, side: THREE.DoubleSide, emissive: 0xffffff, emissiveMap: tex.glow, emissiveIntensity: 0 });
212	  const mesh = new THREE.Mesh(geo, mat);
213	  mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
